// Kata kunci: dari strategi aktif (hasil analis AI) kalau ada, else fallback daftar di bawah.
// Prinsip: produk impulse-buy 15rb-150rb, komisi bagus, masalah harian.
const DEFAULT_KEYWORDS = [
  'alat dapur unik',
  'organizer rumah',
  'alat kecantikan praktis',
  'aksesorik HP unik',
  'alat mandi praktis',
  'perlengkapan mobil',
  'mainan edukasi anak',
  'alat olahraga rumah'
];
let keywords = DEFAULT_KEYWORDS;
try {
  const changes = $('Load Strategy').item.json.changes || {};
  if (Array.isArray(changes.keywords_id) && changes.keywords_id.length) {
    keywords = changes.keywords_id.map(k => String(k).trim()).filter(Boolean).slice(0, 12);
  }
} catch (e) {
  // strategy belum ada / pairing tidak tersedia → pakai fallback
}
return keywords.map(keyword => ({ json: { keyword, track: 'id' } }));

// Bangun body GraphQL + tanda tangan Shopee Affiliate.
// Skema signing: SHA256(appid + timestamp + body + secret)
const crypto = require('crypto');
const appid = $env.SHOPEE_AFFILIATE_APPID;
const secret = $env.SHOPEE_AFFILIATE_SECRET;
if (!appid || !secret) throw new Error('SHOPEE_AFFILIATE_APPID/SECRET belum diisi di .env');

const out = [];
for (const item of $input.all()) {
  const kw = item.json.keyword;
  const query = `{
    productOfferV2(keyword: "${kw}", listType: 1, sortType: 5, page: 1, limit: 20) {
      nodes {
        itemId productName productLink offerLink imageUrl
        priceMin priceMax priceDiscountRate sales ratingStar
        commissionRate sellerCommissionRate commission
        shopId shopName periodStartTime periodEndTime
      }
      pageInfo { page limit hasNextPage }
    }
  }`;
  const body = JSON.stringify({ query });
  const ts = Math.floor(Date.now() / 1000);
  const sign = crypto.createHash('sha256').update(appid + String(ts) + body + secret).digest('hex');
  out.push({
    json: {
      keyword: kw,
      track: item.json.track,
      body,
      auth: `SHA256 Credential=${appid}, Signature=${sign}, Timestamp=${ts}`
    }
  });
}
return out;

// Normalisasi + skor kurasi.
// Skor: komisi (40%) + penjualan (20%) + rating (15%) + band harga (15%) + diskon (10%)
const keyword = $('Sign Shopee Request').item.json.keyword;
const res = $json;
const nodes = (res && res.data && res.data.productOfferV2 && res.data.productOfferV2.nodes) || [];
const out = [];
for (const n of nodes) {
  const price = Number(n.priceMin || 0);
  const rate = Number(n.commissionRate || 0);
  const sales = Number(n.sales || 0);
  const rating = Number(n.ratingStar || 0);
  const discount = Number(n.priceDiscountRate || 0);

  const rateScore = Math.min(rate / 0.30, 1) * 40;                       // komisi 30% = penuh
  const salesScore = Math.min(Math.log10(sales + 10) / 4, 1) * 20;       // 10rb terjual = penuh
  const ratingScore = Math.min(rating / 5, 1) * 15;
  const priceScore = (price >= 15000 && price <= 150000) ? 15 : (price > 150000 ? 5 : 8);
  const discountScore = Math.min(discount / 40, 1) * 10;
  const score = Math.round((rateScore + salesScore + ratingScore + priceScore + discountScore) * 100) / 100;

  const esc = s => String(s ?? '').replace(/'/g, "''");
  const num = v => (v === null || v === undefined || v === '' || Number.isNaN(Number(v)) ? 'NULL' : Number(v));
  const sql = `INSERT INTO products
    (source, ext_id, track, title, image_url, product_url, offer_url,
     price_min, price_max, discount_rate, sales, rating_star,
     commission_rate, commission_amt, shop_name, score)
  VALUES
    ('shopee', '${esc(n.itemId)}', 'id', '${esc(n.productName)}', '${esc(n.imageUrl)}',
     '${esc(n.productLink)}', '${esc(n.offerLink)}',
     ${num(n.priceMin)}, ${num(n.priceMax)}, ${num(n.priceDiscountRate)}, ${num(n.sales)}, ${num(n.ratingStar)},
     ${num(n.commissionRate)}, ${num(n.commission)}, '${esc(n.shopName)}', ${score})
  ON CONFLICT (source, ext_id)
  DO UPDATE SET score = EXCLUDED.score, updated_at = now();`;
  out.push({ json: { sql, score, title: n.productName, keyword } });
}
return out.length ? out : [{ json: { sql: 'SELECT 1', skipped: true } }];

// Track EN: produk dari tabel seed (program afiliasi luar negeri tanpa API publik).
const out = [];
for (const item of $input.all()) {
  const n = item.json;
  if (!n.name || !n.url) continue;
  const esc = s => String(s ?? '').replace(/'/g, "''");
  // Skor tetap 55 — program recurring (SaaS) diutamakan; feedback loop menaikkan nanti.
  const score = 55;
  const sql = `INSERT INTO products
    (source, ext_id, track, title, image_url, product_url, offer_url,
     commission_rate, shop_name, score)
  VALUES
    ('seed_en', '${esc(n.name)}', 'en', '${esc(n.name)}', '${esc(n.demo_image || '')}',
     '${esc(n.url)}', '${esc(n.url)}', NULL, '${esc(n.program + ': ' + (n.commission || ''))}', ${score})
  ON CONFLICT (source, ext_id)
  DO UPDATE SET score = EXCLUDED.score, updated_at = now();`;
  out.push({ json: { sql, title: n.name } });
}
return out.length ? out : [{ json: { sql: 'SELECT 1', skipped: true } }];

